import Foundation

func block(_ id: String, _ ordinal: Int, _ kind: String = "text", _ text: String? = nil, _ payload: [String: NativeLiveJSONValue]? = nil, raw: String? = nil) -> NativeLiveCurrentPathBlock {
    .init(id: id, ordinal: ordinal, kind: kind, rawType: raw ?? kind, text: text, payload: payload, createdAt: "")
}
func message(_ blocks: [NativeLiveCurrentPathBlock], role: String = "user") -> NativeLiveCurrentPathMessage {
    .init(id: "m1", conversationId: "c1", parentMessageId: nil, role: role, status: "completed", createdAt: "", completedAt: nil, blocks: blocks)
}
func project(_ blocks: [NativeLiveCurrentPathBlock], role: String = "user") -> NativeLiveMessagePresentation {
    NativeLiveMessagePresentationProjector.project(.canonical(message(blocks, role: role)))
}
let user = project([block("t1", 0, "text", " hello ")])
precondition(user.role == "user" && user.nodes.count == 1)
precondition(user.nodes[0].kind == .markdown && user.nodes[0].canonicalIdentity == "text")
precondition(user.copyText == "hello")
let assistant = project([block("a1", 0, "text", "answer")], role: "assistant")
precondition(assistant.role == "assistant" && assistant.copyText == "answer")
let attachmentPayload: [String: NativeLiveJSONValue] = ["attachment_id": .string("file1"), "filename": .string("report.pdf"), "mime_type": .string("application/pdf"), "kind": .string("file"), "refs": .array([.object(["type": .string("attachment_ref"), "entity_id": .string("file1")])]), "provenance": .object(["origin": .string("user_send")])]
let attachment = block("file-block", 1, "attachment", nil, attachmentPayload)
let mixed = project([block("t2", 2, "text", "second"), attachment, block("t0", 0, "text", "first")])
precondition(mixed.nodes.map(\.ordinal) == [0, 1, 2])
precondition(mixed.nodes.map(\.id) == ["t0", "file-block", "t2"])
precondition(mixed.copyText == "first\n\nsecond")
precondition(mixed.nodes[1].entityRefs == attachmentPayload["refs"]?.arrayValue)
precondition(mixed.nodes[1].provenance == attachmentPayload["provenance"])
precondition(mixed.nodes[1].materialization == "ready")
let tied = project([block("first-tie", 4, "text", "one"), block("second-tie", 4, "text", "two")])
precondition(tied.nodes.map(\.id) == ["first-tie", "second-tie"])
precondition(project([attachment]).nodes.count == 1 && project([attachment]).copyText == nil)
let evidence = [block("use", 0, "tool_use", "do not copy", ["tool_use_id": .string("read1")]), block("result", 1, "tool_result", "do not show", ["output": .string("file contents")])]
precondition(project(evidence, role: "assistant").nodes.isEmpty)
precondition(project(evidence, role: "assistant").copyText == nil)
precondition(message(evidence).blocks.count == 2)
let unknown = project([block("future", 5, "unknown", nil, ["diagnostic_code": .string("UNSUPPORTED_PROVIDER_CONTENT"), "filename": .string("report"), "thinking": .string("SECRET"), "huge": .string(String(repeating: "x", count: 100000))], raw: "future_widget")])
precondition(unknown.nodes.count == 1 && unknown.nodes[0].kind == .unknown)
precondition(unknown.nodes[0].rawType == "future_widget")
precondition(unknown.nodes[0].fallback.diagnostic == "UNSUPPORTED_PROVIDER_CONTENT")
precondition(unknown.nodes[0].fallback.metadata["filename"] == "report")
precondition(unknown.nodes[0].fallback.metadata["thinking"] == nil && unknown.nodes[0].fallback.metadata["huge"] == nil)
precondition(NativeLiveMessageRendererRegistry.renderer(for: unknown.nodes[0]) == .fallback)
for identity in ["artifact", "resource", "canonical_tool_result"] {
    let result = project([block(identity, 0, identity)])
    precondition(result.nodes[0].canonicalIdentity == identity)
    precondition(NativeLiveMessageRendererRegistry.renderer(for: result.nodes[0]) == .fallback)
}
for kind in NativeLiveVisualNodeKind.allCases where kind != .markdown && kind != .text && kind != .attachment {
    precondition(NativeLiveMessageRendererRegistry.renderer(for: kind) == .fallback)
}
let voice = project([block("voice", 0, "text", "transcript", ["input_mode": .string("voice")])])
precondition(voice.isVoiceInput && voice.nodes[0].inputMode == "voice" && voice.nodes[0].canonicalIdentity == "text")
let draftAttachment = NativeLiveAttachmentPresentationInput(entityID: "file1", draftID: "draft-file", filename: "report.pdf", mimeType: "application/pdf", kind: "file", materialization: "ready")
let draft = NativeLiveMessagePresentationSource.send(messageID: "m1", text: "hello", attachments: [draftAttachment])
let pending = NativeLiveMessagePresentationProjector.project(draft)
let equivalent = project([block("m1:text", 0, "text", "hello"), block("attachment:file1", 1, "attachment", nil, attachmentPayload, raw: "file")])
precondition(pending.role == equivalent.role && pending.copyText == equivalent.copyText)
precondition(pending.nodes.map(\.kind) == equivalent.nodes.map(\.kind))
precondition(pending.nodes.map(\.ordinal) == equivalent.nodes.map(\.ordinal))
precondition(pending.nodes[1].attachment?.entityID == "file1" && equivalent.nodes[1].attachment?.entityID == "file1")
precondition(pending.nodes[1].materialization == "ready" && equivalent.nodes[1].materialization == "ready")
precondition(pending.nodes.map(\.canonicalIdentity) == ["text", "attachment"])
let voiceDraft = NativeLiveMessagePresentationProjector.project(.send(messageID: "voice-draft", text: "transcript", inputMode: .voice))
precondition(voiceDraft.isVoiceInput && voiceDraft.nodes[0].canonicalIdentity == "text")
let emptyDraft = NativeLiveMessagePresentationProjector.project(.send(messageID: "empty", text: " ", attachments: [draftAttachment]))
precondition(emptyDraft.nodes.count == 1 && emptyDraft.nodes[0].kind == .attachment)
let uploading = NativeLiveComposerAttachmentDraft(filename: "image.png", mimeType: "image/png", kind: .image, data: Data([1, 2]))
precondition(uploading.presentationInput.entityID == nil && uploading.presentationInput.materialization == "uploading")
let uploadingPresentation = NativeLiveMessagePresentationProjector.project(.send(messageID: "uploading", text: "", attachments: [uploading.presentationInput]))
precondition(uploadingPresentation.nodes[0].kind == .attachment && NativeLiveMessageRendererRegistry.renderer(for: uploadingPresentation.nodes[0]) == .attachment)
let original = message([block("old-text", 0, "text", "old voice", ["input_mode": .string("voice")]), attachment])
let editSource = NativeLiveMessagePresentationSource.edit(original, text: "keyboard edit")
let edit = NativeLiveMessagePresentationProjector.project(editSource)
let canonicalEdit = project([block("old-text", 0, "text", "keyboard edit"), attachment])
precondition(edit.messageID == original.id && edit.nodes.map(\.sourceBlock) == canonicalEdit.nodes.map(\.sourceBlock))
precondition(edit.nodes.map(\.kind) == canonicalEdit.nodes.map(\.kind))
precondition(edit.attachmentInputs[0].metadata == canonicalEdit.attachmentInputs[0].metadata)
precondition(edit.attachmentInputs[0].source == .retainedEdit && canonicalEdit.attachmentInputs[0].source == .authoritative)
precondition(!edit.isVoiceInput && edit.nodes[0].inputMode == nil)
precondition(edit.nodes[1].sourceBlock == attachment && edit.copyText == "keyboard edit")
precondition(original.blocks[0].payload?["input_mode"]?.stringValue == "voice")
let removed = NativeLiveMessagePresentationProjector.project(.edit(original, text: "edit", attachments: []))
precondition(removed.nodes.count == 1 && removed.nodes[0].kind == .markdown)
let attachmentEdit = NativeLiveMessagePresentationProjector.project(.edit(message([attachment]), text: ""))
precondition(attachmentEdit.nodes.count == 1 && attachmentEdit.copyText == nil)


precondition(mixed.attachmentInputs.count == 1)
precondition(mixed.attachmentInputs[0].retainedComposerDraft?.remoteAttachmentID == "file1")
precondition(uploading.presentationInput.retainedComposerDraft == nil)
let invalidAttachment = project([block("invalid", 0, "attachment", nil, ["attachment_id": .string("")])])
precondition(NativeLiveMessageRendererRegistry.renderer(for: invalidAttachment.nodes[0]) == .fallback)

let operation = NativeLivePendingOperation(kind: .send(text: "transcript"), baselineSyncToken: "before", presentationAttachments: [draftAttachment], inputMode: .voice)
let rebased = operation.rebased(to: "after")
precondition(rebased.id == operation.id && rebased.presentationAttachments == operation.presentationAttachments && rebased.inputMode == .voice && rebased.sendText == "transcript")
let history = NativeLiveMessagePresentationProjector.project(.history(.init(ordinal: 3, role: "assistant", time: "", content: "historical text")))
precondition(history.role == "assistant" && history.copyText == "historical text" && history.nodes[0].canonicalIdentity == "text")
let zeroAttachment = block("zero-file", 0, "attachment", nil, attachmentPayload)
let textAdded = NativeLiveMessagePresentationProjector.project(.edit(message([zeroAttachment]), text: "added"))
precondition(textAdded.nodes.map(\.canonicalIdentity) == ["text", "attachment"])
precondition(textAdded.nodes.map(\.ordinal) == [0, 1])
precondition(textAdded.nodes[1].id == zeroAttachment.id && textAdded.nodes[1].provenance == zeroAttachment.payload?["provenance"])
precondition(emptyDraft.nodes[0].ordinal == 0)
let textRemoved = NativeLiveMessagePresentationProjector.project(.edit(original, text: ""))
precondition(textRemoved.nodes[0].ordinal == 0 && textRemoved.nodes[0].id == attachment.id)
print("Message presentation behavior passed: canonical, draft, Edit, metadata, Activity, voice, fallback, copy")
